// Package catalogue holds public SDR receivers that can hear amateur
// satellites, built from the WebSDR project's server list.
package catalogue

// Band is a tuning range a receiver offers, in kHz.
type Band struct {
	Name          string
	CenterKHz     float64
	SampleRateKHz float64
}

// LowHz is the low edge of the band, in Hz.
func (b Band) LowHz() float64 { return (b.CenterKHz - b.SampleRateKHz/2) * 1000 }

// HighHz is the high edge of the band, in Hz.
func (b Band) HighHz() float64 { return (b.CenterKHz + b.SampleRateKHz/2) * 1000 }

// Covers reports whether the band contains frequencyHz.
func (b Band) Covers(frequencyHz float64) bool {
	return b.LowHz() <= frequencyHz && frequencyHz <= b.HighHz()
}

// Receiver is one public receiver and the bands it publishes.
type Receiver struct {
	URL            string
	Kind           string
	Latitude       float64
	Longitude      float64
	Bands          []Band
	SatelliteBands []string
}

// CanHear reports whether any published band covers frequencyHz.
func (r Receiver) CanHear(frequencyHz float64) bool {
	for _, band := range r.Bands {
		if band.Covers(frequencyHz) {
			return true
		}
	}
	return false
}

// BandFor returns the band covering frequencyHz, if any.
func (r Receiver) BandFor(frequencyHz float64) (Band, bool) {
	for _, band := range r.Bands {
		if band.Covers(frequencyHz) {
			return band, true
		}
	}
	return Band{}, false
}

